-- Replace PROJECT_ID before running.
CREATE SCHEMA IF NOT EXISTS `PROJECT_ID.revolut_bronze` OPTIONS(location='US');
CREATE SCHEMA IF NOT EXISTS `PROJECT_ID.revolut_silver` OPTIONS(location='US');
CREATE SCHEMA IF NOT EXISTS `PROJECT_ID.revolut_gold` OPTIONS(location='US');
CREATE SCHEMA IF NOT EXISTS `PROJECT_ID.revolut_snapshots` OPTIONS(location='US');

CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.BRANCHES_bronze` (BranchID STRING, BranchName STRING, City STRING, Country STRING, SortCodePrefix STRING, Region STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY BranchID,batch_id;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.CUSTOMERS_bronze` (CustomerID STRING,FirstName STRING,LastName STRING,Email STRING,Phone STRING,DateOfBirth STRING,City STRING,Country STRING,RiskRating STRING,UpdatedAt STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY CustomerID,batch_id;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.EMPLOYEES_bronze` (EmployeeID STRING,BranchID STRING,FirstName STRING,LastName STRING,Role STRING,HireDate STRING,Status STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY EmployeeID,BranchID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.ACCOUNTTYPES_bronze` (AccountTypeID STRING,AccountType STRING,ProductCategory STRING,MonthlyFee STRING,InterestRate STRING,OverdraftLimit STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY AccountTypeID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.ACCOUNTS_bronze` (AccountID STRING,CustomerID STRING,AccountTypeID STRING,BranchID STRING,SortCode STRING,AccountNumber STRING,Currency STRING,Balance STRING,OpenDate STRING,CloseDate STRING,Status STRING,UpdatedAt STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY AccountID,CustomerID,batch_id;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.CARDS_bronze` (CardID STRING,AccountID STRING,CardType STRING,Network STRING,IssueDate STRING,ExpiryDate STRING,Status STRING,ContactlessEnabled STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY CardID,AccountID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.TRANSACTIONTYPES_bronze` (TransactionTypeID STRING,TransactionType STRING,Category STRING,Direction STRING,IsCashProxy STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY TransactionTypeID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.TRANSACTIONS_bronze` (TransactionID STRING,AccountID STRING,TransactionTypeID STRING,TransactionTs STRING,Amount STRING,Currency STRING,Channel STRING,MerchantCategory STRING,Reference STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY AccountID,TransactionID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.LOANS_bronze` (LoanID STRING,CustomerID STRING,BranchID STRING,LoanType STRING,PrincipalAmount STRING,InterestRate STRING,StartDate STRING,EndDate STRING,Status STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY LoanID,CustomerID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.LOANPAYMENTS_bronze` (PaymentID STRING,LoanID STRING,PaymentDate STRING,DueDate STRING,Amount STRING,PaymentStatus STRING,batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,source_row_number INT64,file_hash STRING,ingestion_ts TIMESTAMP) PARTITION BY business_date CLUSTER BY LoanID,PaymentID;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.CONTROL_TABLE_bronze` (batch_id STRING,business_date DATE,load_type STRING,source_file STRING,source_path STRING,file_hash STRING,entity_name STRING,target_table STRING,source_row_count INT64,bronze_row_count INT64,rejected_row_count INT64,processing_status STRING,pipeline_status STRING,start_time TIMESTAMP,end_time TIMESTAMP,error_message STRING,created_at TIMESTAMP) PARTITION BY business_date CLUSTER BY batch_id,entity_name,processing_status;
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.ENTITY_CONFIG_bronze` (entity_name STRING,target_table STRING,primary_key STRING,expected_columns ARRAY<STRING>,active_flag BOOL,updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.COLUMN_CONFIG_bronze` (
  entity_name STRING,
  column_name STRING,
  ordinal_position INT64,
  silver_data_type STRING,
  required_flag BOOL,
  updated_at TIMESTAMP
);
CREATE TABLE IF NOT EXISTS `PROJECT_ID.revolut_bronze.VALIDATION_RULES_bronze` (rule_id STRING,entity STRING,rule_name STRING,severity STRING,treatment STRING,active_flag BOOL,updated_at TIMESTAMP);
